<?php
require 'config/database.php';require 'includes/auth.php';require_role('personnel');$message='';
if($_SERVER['REQUEST_METHOD']==='POST'){$code=trim($_POST['code']??'');$q=$pdo->prepare("SELECT r.*,u.name AS student_name,w.name AS reward_name FROM redemptions r JOIN users u ON u.id=r.user_id JOIN rewards w ON w.id=r.reward_id WHERE r.code=?");$q->execute([$code]);$claim=$q->fetch();if($claim&&$claim['status']==='pending'){$pdo->prepare("UPDATE redemptions SET status='completed',claimed_by=?,claimed_at=NOW() WHERE id=?")->execute([current_user()['id'],$claim['id']]);$message='Claim verified and marked completed for '.$claim['student_name'].' ('.$claim['reward_name'].').';}else{$message='Code not found or this redemption has already been processed.';}}
$claims=$pdo->query("SELECT r.*,u.name AS student_name,w.name AS reward_name FROM redemptions r JOIN users u ON u.id=r.user_id JOIN rewards w ON w.id=r.reward_id ORDER BY r.created_at DESC")->fetchAll();$pageTitle='Personnel claims';include 'includes/header.php';?>
<div class="page-heading"><span class="eyebrow">KINS OFFICE · PERSONNEL</span><h1>Redemption claims</h1><p>Verify the student's unique code before releasing the reserved reward.</p></div>
<?php if($message):?><div class="notice success"><?=htmlspecialchars($message)?></div><?php endif;?>
<div class="two-col"><form class="panel form-panel" method="post"><h2>Verify a redemption code</h2><label>Unique redemption code<input name="code" required placeholder="Enter code"></label><button class="btn primary full">Verify and complete claim</button></form><section class="panel"><h2>Recent claims</h2><?php foreach($claims as $c):?><div class="claim-row"><div><b><?=htmlspecialchars($c['reward_name'])?></b><small><?=htmlspecialchars($c['student_name'])?> · <?=htmlspecialchars($c['code'])?></small></div><span class="status <?=$c['status']?>"><?=htmlspecialchars($c['status'])?></span></div><?php endforeach;?></section></div>
<?php include 'includes/footer.php';?>
